// @couli/db: Kysely + pg access to the `app` schema (ADR-0001 §2).
// Table types come from `db.gen.ts`, generated by `pnpm db:snapshot`; never edit that file.
import { Kysely, PostgresDialect, type PostgresPool } from 'kysely';
import pg from 'pg';

import type { DB } from './db.gen.ts';
import { parseInt8, parseInt8Array } from './int8.ts';

export type { DB } from './db.gen.ts';
export {
  MONTH_PARTITIONED_TABLES,
  MONTHS_AHEAD,
  monthPartitionName,
  monthStartDate,
  monthsToEnsure,
  utcMonthStart,
} from './partitions.ts';
export type { MonthPartitionedTable } from './partitions.ts';
export { parsePgUrl, pgUrl, redactPgUrl } from './pg-url.ts';
export type { PgUrlOverrides, PgUrlParts } from './pg-url.ts';

/** Schema that holds every business table. */
export const APP_SCHEMA = 'app';

export type CreateDbOptions = {
  /** Pool size; per-process values are listed in ADR-0001 §4.2 #11. */
  max?: number;
  applicationName?: string;
} & (
  | { connectionString: string; poolFactory?: (config: pg.PoolConfig) => PostgresPool }
  // Platform infrastructure supplies its own discrete connection fields and lifecycle.
  | { connectionString?: never; poolFactory: (config: pg.PoolConfig) => PostgresPool }
);

const INT8_ARRAY_OID = 1016;

// int8 and int8[] are parsed as BigInt (ADR-0001 §4.2 #3). The override is scoped to pools
// created here, so libraries that own their connections (pg-boss, node-pg-migrate) keep pg's
// defaults.
function int8AsBigInt(): pg.TypeOverrides {
  const overrides = new pg.TypeOverrides();
  overrides.setTypeParser(pg.types.builtins.INT8, parseInt8);
  overrides.setTypeParser(INT8_ARRAY_OID, parseInt8Array);
  return overrides;
}

// A disconnected backend surfaces as an 'error' event: on the pool while the client is idle,
// and on the client itself while it is checked out (pg-pool only listens to idle clients).
// Neither emitter may be left without a listener, or Node turns the event into an uncaught
// exception. The listeners only absorb the event: pg-pool already drops an idle client that
// errors, and drops a checked-out one on release because it is no longer queryable, so
// releasing, destroying or rebuilding anything here would double-handle it. The query that
// was running, or the next one on that lease, still rejects through its own promise.
// This package has no logger, so nothing is reported here.
function ignoreConnectionError(): void {}

class DefaultClient extends pg.Client {
  constructor(clientConfig?: pg.ClientConfig) {
    super(clientConfig);
    this.on('error', ignoreConnectionError);
  }
}

/** Pool used when the caller supplies no poolFactory; factory pools are left untouched. */
function defaultPool(config: pg.PoolConfig): pg.Pool {
  const pool = new pg.Pool({ ...config, Client: DefaultClient });
  pool.on('error', ignoreConnectionError);
  return pool;
}

/**
 * Creates a Kysely instance bound to schema `app`, backed by its own pg pool.
 * Call `destroyDb` to close the pool.
 *
 * Platform-managed handles supply poolFactory for error handling and bounded shutdown.
 */
export function createDb(opts: CreateDbOptions): Kysely<DB> {
  const config: pg.PoolConfig = {
    types: int8AsBigInt(),
  };
  if (opts.connectionString !== undefined) {
    config.connectionString = opts.connectionString;
  }
  if (opts.max !== undefined) {
    config.max = opts.max;
  }
  if (opts.applicationName !== undefined) {
    config.application_name = opts.applicationName;
  }
  const pool = opts.poolFactory?.(config) ?? defaultPool(config);
  return new Kysely<DB>({ dialect: new PostgresDialect({ pool }) }).withSchema(APP_SCHEMA);
}

/** Closes the pool behind a Kysely instance created by `createDb`. */
export async function destroyDb(db: Kysely<DB>): Promise<void> {
  await db.destroy();
}
